import clsx from 'clsx';
import React from 'react';

import { suggestionGroupLabelCSS } from './SuggestionGroupLabel.sty.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { Text } from '../../../typography/Text.js';

export type FilterFieldSuggestionGroupLabelProps = WithChildren &
  StylingProps &
  DataTestId;

export const SuggestionGroupLabel = (
  props: FilterFieldSuggestionGroupLabelProps,
) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <Text
      textStyle="base"
      data-testid={dataTestId}
      className={clsx(suggestionGroupLabelCSS, consumerClassName)}
      style={consumerStyle}
      as="p"
    >
      {children}
    </Text>
  );
};

SuggestionGroupLabel.displayValue = 'FilterField.SuggestionGroupLabel';
